package com.example.deviceguard;
import android.os.Bundle;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.deviceguard.models.*;import com.example.deviceguard.network.*;import com.example.deviceguard.utils.*;import java.text.*;import java.util.*;import retrofit2.*;
public class HistoryActivity extends AppCompatActivity{private LinearLayout list;private ApiService api;private String deviceId;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_history);list=findViewById(R.id.historyList);deviceId=getIntent().getStringExtra("deviceId");String name=getIntent().getStringExtra("deviceName");((TextView)findViewById(R.id.title)).setText((name==null?"Device":name)+" • Location History");api=RetrofitClient.get(this);load();}
private void load(){api.history(deviceId,100).enqueue(new Callback<LocationsResponse>(){public void onResponse(Call<LocationsResponse>c,Response<LocationsResponse>r){if(!r.isSuccessful()){add("Error: "+ApiError.message(r));return;}if(r.body().locations==null||r.body().locations.isEmpty()){add("No location history yet.");return;}SimpleDateFormat f=new SimpleDateFormat("dd MMM yyyy, hh:mm:ss a",Locale.getDefault());for(LocationPoint p:r.body().locations){TextView t=new TextView(HistoryActivity.this);t.setText("📍 "+String.format(Locale.US,"%.6f, %.6f",p.latitude,p.longitude)+"\n"+f.format(parseTimestamp(p.timestamp))+"\nAccuracy: "+(p.accuracy==null?"Unknown":String.format(Locale.US,"%.1f m",p.accuracy)));t.setTextSize(15);t.setPadding(14,14,14,14);list.addView(t);View sep=new View(HistoryActivity.this);sep.setLayoutParams(new LinearLayout.LayoutParams(-1,1));list.addView(sep);}}public void onFailure(Call<LocationsResponse>c,Throwable t){add("Network error: "+t.getMessage());}});}
private Date parseTimestamp(String value){String[] patterns={"yyyy-MM-dd'T'HH:mm:ss.SSSX","yyyy-MM-dd'T'HH:mm:ssX"};for(String pattern:patterns){try{return new SimpleDateFormat(pattern,Locale.US).parse(value);}catch(Exception ignored){}}return new Date();}
private void add(String s){TextView t=new TextView(this);t.setText(s);t.setPadding(8,20,8,20);list.addView(t);}}
